mapper.select:
SELECT content_id, title, source_url, platform, publish_time, keywords, category, author_name, like_count, comment_count, repost_count, favorite_count FROM ads_content_hot_rank
WHERE event_id = #{eventId}
AND platform IN ('SOHU_NEWS', 'TENCENT_NEWS', 'NETEASE_NEWS', 'SINA_NEWS', 'THE_PAPER')
AND NULLIF(TRIM(keywords), '') IS NOT NULL
ORDER BY publish_time DESC, id DESC
LIMIT #{limit}
